/**
 * Map geometry (generated by tools/map/build.ts) and the land mask for instant pin feedback.
 * Both are loaded only when a map is shown, so they are not part of the main bundle.
 */
import maskUrl from '../../../../shared/data/landmask.bin?url';

export interface Country {
  readonly id: string;
  readonly name: string;
  /** English name where it differs (v0.4). */
  readonly nameEn?: string;
  readonly area: number;
  readonly d: string;
  readonly label: readonly [number, number] | null;
}

/**
 * A city with more than 200 000 inhabitants in the section (`big`: more than one million), v0.7
 * outside the section capitals only (always `big`); largest first.
 */
export interface City {
  readonly name: string;
  /** English name where it differs (v0.4). */
  readonly nameEn?: string;
  readonly big: boolean;
  readonly x: number;
  readonly y: number;
}

export interface MapData {
  /** v0.7: the whole world (Equal Earth, km; SVG y downwards). */
  readonly viewBox: readonly [number, number, number, number];
  /** v0.7: the European section, where homes are (registration and moving stay inside). */
  readonly europe: readonly [number, number, number, number];
  /** v0.7: the edge of the world (filled as sea). */
  readonly outline: string;
  readonly countries: readonly Country[];
  readonly lakes: string;
  readonly cities: readonly City[];
}

let data: Promise<MapData> | undefined;

export function loadMapData(): Promise<MapData> {
  data ??= import('./world.json').then((module) => module.default as unknown as MapData);
  return data;
}

let mask: Promise<Uint8Array> | undefined;

/**
 * The server's check is authoritative (SPEC 12.3). v0.6: a failed download (offline, or aborted
 * by leaving the page) is not cached, so the next call tries again.
 */
export function landMask(): Promise<Uint8Array> {
  mask ??= fetch(maskUrl)
    .then((response) => {
      if (!response.ok) throw new Error(`land mask: ${response.status}`);
      return response.arrayBuffer();
    })
    .then((buffer) => new Uint8Array(buffer))
    .catch((error: unknown) => {
      mask = undefined;
      throw error;
    });
  return mask;
}

/** Loads the mask ahead of time; a failure here is harmless (loaded again when needed). */
export function preloadLandMask(): void {
  landMask().catch(() => undefined);
}
